import fs from "node:fs";
import path from "node:path";

const root = path.resolve(new URL("..", import.meta.url).pathname);
function read(name) { return fs.readFileSync(path.join(root, "src", name), "utf8"); }
function exportsOf(text) {
  return [...text.matchAll(/^export\s+(?:async\s+)?(?:const|class|function)\s+([A-Za-z_$][\w$]*)/gm)].map((match) => match[1]);
}
function importNames(text, source) {
  const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const match = text.match(new RegExp(`^import\\s*\\{([^}]*)\\}\\s*from\\s*["']\\./${escaped}["'];`, "m"));
  if (!match) throw new Error(`Missing import from ${source}`);
  return `{ ${match[1].split(",").map((name) => name.trim()).filter(Boolean).join(", ")} }`;
}
function stripExports(text) {
  return text
    .replace(/^export\s+\{[\s\S]*?\};\s*$/gm, "")
    .replace(/^export\s+/gm, "");
}
function stripImports(text) { return text.replace(/^import\s*\{[\s\S]*?\}\s*from\s*["'][^"']+["'];\s*\n/gm, ""); }
function moduleBlock(name, text, exports, parameters = "", args = "") {
  return `const ${name} = ((${parameters}) => {\n${stripExports(stripImports(text))}\nreturn {\n  ${exports.join(",\n  ")}\n};\n})(${args});\n\n`;
}

const modules = [
  ["face-model.js", "SportsFaceModel"],
  ["player-expression.js", "SportsFaceExpression"],
  ["gnm-assets.js", "SportsFaceGnmAssets"],
  ["gnm-player-model.js", "SportsFaceGnmPlayerModel"],
  ["gnm-player-lighting.js", "SportsFaceGnmPlayerLighting"],
  ["gnm-player-eyes.js", "SportsFaceGnmPlayerEyes"],
  ["gnm-player-post.js", "SportsFaceGnmPlayerPost"],
  ["gnm-player-hair.js", "SportsFaceGnmPlayerHair"],
  ["gnm-player-facial-hair.js", "SportsFaceGnmPlayerFacialHair"],
  ["gnm-player-renderer.js", "SportsFaceGnmPlayerRenderer"],
  ["render-router.js", "SportsFaceRenderRouter"],
];
const names = new Map(modules);
let out = "/* Sports Face 3D player browser bundle. Generated by npm run build:offline. */\n";
for (const [file, name] of modules) {
  const source = read(file);
  const dependencies = [...source.matchAll(/^import\s*\{[^}]*\}\s*from\s*["']\.\/([^"']+)["'];/gm)].map((match) => match[1]);
  const forwarded = [...source.matchAll(/^export\s*\{([^}]+)\};/gm)].flatMap((match) => match[1].split(",").map((value) => value.trim()));
  out += moduleBlock(name, source, [...exportsOf(source), ...forwarded], dependencies.map((file) => importNames(source, file)).join(", "), dependencies.map((file) => names.get(file)).join(", "));
}
const app = read("app.js");
out += `(() => {\nconst ${importNames(app, "face-model.js")} = SportsFaceModel;\nconst ${importNames(app, "render-router.js")} = SportsFaceRenderRouter;\n${stripImports(app)}\n})();\n`;
fs.writeFileSync(path.join(root, "src", "app.bundle.js"), out);
console.log(`Built src/app.bundle.js (${out.length} bytes)`);
